                var marketNames = { peru: 'Peru', brazil: 'Brazil', canada: 'Canada', australia: 'Australia' };
                var marketNamesEs = { peru: 'Perú', brazil: 'Brasil', canada: 'Canadá', australia: 'Australia' };
                for (var mi = 0; mi < markets.length; mi++) {
                    var mk = markets[mi];
                    var modeKey = mk + 'Mode';
                    if (ds[modeKey]) {
                        html += '<div class="msp-entry-sim-decision-group">';
                        html += '<label>' + (lang === 'es' ? 'Revisión de Portafolio: ' + marketNamesEs[mk] : 'Portfolio Review: ' + marketNames[mk]) + '</label>';
                        html += '<select id="review_' + mk + '">';
                        html += '<option value="deepen">' + (lang === 'es' ? 'Profundizar inversión' : 'Deepen investment') + '</option>';
                        html += '<option value="maintain">' + (lang === 'es' ? 'Mantener operaciones' : 'Maintain operations') + '</option>';
                        html += '<option value="restructure">' + (lang === 'es' ? 'Reestructurar modo de entrada' : 'Restructure entry mode') + '</option>';
                        html += '<option value="exit">' + (lang === 'es' ? 'Salir del mercado' : 'Exit market') + '</option>';
                        html += '</select></div>';
                    }
                }

                html += '<div class="msp-entry-sim-decision-group">';
                html += '<label data-i18n="org_arch_label">' + (lang === 'es' ? 'Arquitectura Organizacional' : 'Organizational Architecture') + '</label>';
                html += '<select id="primaryInput">';
                html += '<option value="international_div">' + (lang === 'es' ? 'División Internacional (doméstico/internacional)' : 'International Division (domestic/international split)') + '</option>';
                html += '<option value="global_product">' + (lang === 'es' ? 'División Global por Producto/Servicio' : 'Global Product/Service Division') + '</option>';
                html += '<option value="geographic">' + (lang === 'es' ? 'Estructura por Área Geográfica' : 'Geographic Area Structure') + '</option>';
                html += '<option value="matrix">' + (lang === 'es' ? 'Matriz (línea de servicio x geografía)' : 'Matrix (service line x geography)') + '</option>';
                html += '</select></div>';
            }

            dynPanel.innerHTML = html;

            this._updateMarketGrid(ds, lang);
        }

        _updateMarketGrid(ds, lang) {
            var gridEl = document.getElementById('marketGrid');
            if (!gridEl) return;

            var markets = [
                { key: 'peru', name: 'Peru', nameEs: 'Perú', flag: '\ud83c\uddf5\ud83c\uddea' },
                { key: 'brazil', name: 'Brazil', nameEs: 'Brasil', flag: '\ud83c\udde7\ud83c\uddf7' },
                { key: 'canada', name: 'Canada', nameEs: 'Canadá', flag: '\ud83c\udde8\ud83c\udde6' },
                { key: 'australia', name: 'Australia', nameEs: 'Australia', flag: '\ud83c\udde6\ud83c\uddfa' }
            ];

            var html = '';
            for (var i = 0; i < markets.length; i++) {
                var m = markets[i];
                var modeKey = m.key + 'Mode';
                var penKey = m.key + 'Penetration';
                var mode = ds[modeKey] || '';
                var pen = ds[penKey] || 0;
                var isActive = mode !== '';
                var statusClass = isActive ? 'active' : 'pending';

                var modeName = '';
                if (mode && this.ENTRY_MODES[mode]) {
                    modeName = lang === 'es' ? this.ENTRY_MODES[mode].label_es : this.ENTRY_MODES[mode].label_en;
                }

                html += '<div class="msp-entry-sim-market-card ' + statusClass + '">';
                html += '<h5>' + m.flag + ' ' + (lang === 'es' ? m.nameEs : m.name) + '</h5>';
                if (isActive) {
                    html += '<div class="msp-entry-sim-market-mode">' + modeName + '</div>';
                    html += '<div class="msp-entry-sim-market-status" style="color:#2e7d32;">' + (lang === 'es' ? 'Penetración: ' : 'Penetration: ') + pen.toFixed(1) + '%</div>';
                } else {
                    html += '<div class="msp-entry-sim-market-mode" style="color:#999;">' + (lang === 'es' ? 'Pendiente' : 'Pending') + '</div>';
                }
                html += '</div>';
            }
            gridEl.innerHTML = html;
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            var primary = document.getElementById('primaryInput');
            if (primary) decisions.primary = primary.value;

            var secondary = document.getElementById('secondaryInput');
            if (secondary) decisions.secondary = secondary.value;

            var tertiary = document.getElementById('tertiaryInput');
            if (tertiary) decisions.tertiary = tertiary.value;

            var budgetEl = document.getElementById('budgetInput');
            if (budgetEl) decisions.budgetAlloc = parseFloat(budgetEl.value);

            if (period === 1) {
                if (!decisions.budgetAlloc || decisions.budgetAlloc < 0.5 || decisions.budgetAlloc > 3.3) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_warning'), 'warning'
                    );
                    return false;
                }
            }

            if (period === 4) {
                var markets = ['peru', 'brazil', 'canada', 'australia'];
                decisions.portfolioReview = {};
                for (var i = 0; i < markets.length; i++) {
                    var revEl = document.getElementById('review_' + markets[i]);
                    if (revEl) decisions.portfolioReview[markets[i]] = revEl.value;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundIdx = period - 1;

            var events = this.RANDOM_EVENTS[roundIdx] || [];
            var triggeredEvents = [];
            for (var ei = 0; ei < events.length; ei++) {
                var ev = events[ei];
                if (ev.condition === 'brazil_jv' && ds.brazilMode !== 'jv') continue;
                if (Math.random() < ev.prob) {
                    triggeredEvents.push({ round: roundIdx, text_en: ev.text_en, text_es: ev.text_es, effect: ev.effect });
                    if (ev.effect === 'copper_crash') ds.copperCrash = true;
                    if (ev.effect === 'canada_tax_credit') ds.canadaTaxCredit = true;
                    if (ev.effect === 'codelco_standard') ds.codelcoStandard = true;
                }
            }
            ds.activeEvents = (ds.activeEvents || []).concat(triggeredEvents);

            var roundIRR = 0;
            var newLicenses = 0;
            var ipDelta = 0;
            var gcpiDelta = 0;
            var budgetUsed = 0;
            var capDelta = 0;

            if (period === 1) {
                ds.peruMode = d.primary;
                ds.brazilMode = d.secondary;
                ds.peruBudget = d.budgetAlloc;
                ds.brazilBudget = 3.8 - d.budgetAlloc;
                budgetUsed = 3.8;

                var peruModeData = this.ENTRY_MODES[ds.peruMode] || this.ENTRY_MODES['branch'];
                var brazilModeData = this.ENTRY_MODES[ds.brazilMode] || this.ENTRY_MODES['export'];

                var peruOLIfit = this._calcOLIfit('peru', ds.peruMode);
                var brazilOLIfit = this._calcOLIfit('brazil', ds.brazilMode);

                ds.peruPenetration = (peruOLIfit * peruModeData.speed * ds.peruBudget / 2.0) * (3 + Math.random() * 2);
                ds.peruPenetration = Math.min(ds.peruPenetration, 15);
                ds.brazilPenetration = (brazilOLIfit * brazilModeData.speed * ds.brazilBudget / 3.5) * (2 + Math.random());
                ds.brazilPenetration = Math.min(ds.brazilPenetration, 10);

                var peruHasRegEvent = triggeredEvents.some(function(e) { return e.effect === 'peru_regulation'; });
                if (peruHasRegEvent) {
                    if (ds.peruMode === 'wos_greenfield') { ds.peruPenetration *= 0.7; budgetUsed += 0.3; }
                    if (ds.peruMode === 'jv') ds.peruPenetration *= 1.15;
                }

                newLicenses = (ds.peruMode === 'licensing' || ds.peruMode === 'jv') ? Math.round(8 + Math.random() * 8) : Math.round(3 + Math.random() * 5);
                newLicenses += (ds.brazilMode === 'licensing') ? Math.round(4 + Math.random() * 4) : Math.round(1 + Math.random() * 3);

                if (ds.peruMode === 'licensing' || ds.brazilMode === 'licensing') ipDelta -= 5;
                if (ds.brazilMode === 'jv') ipDelta -= 8;

                roundIRR = (ds.peruPenetration * 1.2 + ds.brazilPenetration * 0.8) * 0.5 + (Math.random() * 3 - 1);
                capDelta = peruModeData.control * 3 + brazilModeData.control * 2;
                gcpiDelta = 2;
            }

            if (period === 2) {
                ds.brazilCorrection = d.primary;
                ds.canadaMode = d.secondary;
                ds.competIntel = (d.tertiary === 'yes');
                budgetUsed = 0;

                var canadaModeData = this.ENTRY_MODES[ds.canadaMode] || this.ENTRY_MODES['licensing'];
                if (ds.canadaMode === 'wos_greenfield') budgetUsed += 4.5;
                else if (ds.canadaMode === 'wos_acquisition') budgetUsed += 8.0;
                else if (ds.canadaMode === 'alliance_rd') budgetUsed += 1.5;
                else budgetUsed += 0.8;

                if (ds.canadaTaxCredit && ds.canadaMode === 'wos_greenfield') budgetUsed *= 0.65;
                if (ds.competIntel) budgetUsed += 0.4;

                if (ds.brazilCorrection === 'upgrade_jv' || ds.brazilCorrection === 'upgrade_wos') budgetUsed += 1.5;
                if (ds.brazilCorrection === 'convert_wos') budgetUsed += 2.5;
                if (ds.brazilCorrection === 'escalate_legal') budgetUsed += 0.8;

                var brazilIPevent = triggeredEvents.some(function(e) { return e.effect === 'brazil_ip_dispute'; });
                if (brazilIPevent) {
                    if (ds.brazilCorrection === 'escalate_legal') { ipDelta -= 10; ds.brazilPenetration *= 0.8; }
                    else if (ds.brazilCorrection === 'renegotiate') { ipDelta -= 15; ds.brazilPenetration *= 0.9; }
                    else if (ds.brazilCorrection === 'convert_wos') { ipDelta -= 5; }
                } else {
                    if (ds.brazilCorrection === 'upgrade_jv') ds.brazilPenetration *= 1.3;
                    else if (ds.brazilCorrection === 'upgrade_wos') ds.brazilPenetration *= 1.5;
                    else if (ds.brazilCorrection === 'accelerate') ds.brazilPenetration *= 1.4;
                }

                var canadaOLIfit = this._calcOLIfit('canada', ds.canadaMode);
                ds.canadaPenetration = (canadaOLIfit * canadaModeData.speed * 2) * (1.5 + Math.random());
                ds.canadaPenetration = Math.min(ds.canadaPenetration, 12);
                if (ds.canadaTaxCredit && ds.canadaMode === 'wos_greenfield') ds.canadaPenetration *= 1.25;

                ds.peruPenetration += 2 + Math.random() * 3;
                ds.peruPenetration = Math.min(ds.peruPenetration, 25);

                newLicenses = Math.round(8 + Math.random() * 6);
                if (ds.canadaMode === 'wos_acquisition') newLicenses += Math.round(10 + Math.random() * 5);
                if (ds.canadaMode === 'licensing') newLicenses += Math.round(6 + Math.random() * 4);

                if (ds.canadaMode === 'licensing') ipDelta -= 5;
                if (ds.canadaMode === 'alliance_rd') { ipDelta -= 3; capDelta = 12; }
                else if (ds.canadaMode === 'wos_acquisition') capDelta = 15;
                else capDelta = 5;

                roundIRR = (ds.peruPenetration * 0.8 + ds.brazilPenetration * 0.6 + ds.canadaPenetration * 1.0) * 0.35 + (Math.random() * 2 - 1);
                if (ds.copperCrash) roundIRR -= 3;

                gcpiDelta = ds.competIntel ? 5 : 1;
            }

            if (period === 3) {
                ds.australiaMode = d.primary;
                ds.australiaTiming = d.secondary;
                ds.rioResponse = d.tertiary;
                budgetUsed = 0;

                var ausModeData = this.ENTRY_MODES[ds.australiaMode] || this.ENTRY_MODES['licensing'];
                if (ds.australiaMode === 'wos_greenfield') budgetUsed += 5.5;
                else if (ds.australiaMode === 'wos_acquisition') budgetUsed += 10.0;
                else if (ds.australiaMode === 'alliance_rd') budgetUsed += 1.0;
                else budgetUsed += 0.6;

                var ausRegEvent = triggeredEvents.some(function(e) { return e.effect === 'australia_regulation'; });
                if (ausRegEvent && ds.australiaMode === 'wos_greenfield') { budgetUsed += 2.0; }

                if (ds.rioResponse === 'price_deterrence') budgetUsed += 1.0;
                else if (ds.rioResponse === 'deepen_chile') budgetUsed += 1.5;

                var ausOLIfit = this._calcOLIfit('australia', ds.australiaMode);
                var timingMultiplier = ds.australiaTiming === 'now' ? 1.3 : (ds.australiaTiming === 'delay' ? 0.8 : 1.0);
                ds.australiaPenetration = (ausOLIfit * ausModeData.speed * 1.5) * timingMultiplier * (1 + Math.random() * 0.5);
                ds.australiaPenetration = Math.min(ds.australiaPenetration, 10);
                if (ausRegEvent && (ds.australiaMode === 'wos_acquisition' || ds.australiaMode === 'alliance_rd')) ds.australiaPenetration *= 1.2;

                if (ds.australiaMode === 'licensing') ipDelta -= 5;
                if (ds.australiaMode === 'alliance_rd') ipDelta -= 8;
                if (ds.australiaMode === 'wos_acquisition') capDelta = 12;
                else if (ds.australiaMode === 'alliance_rd') capDelta = 10;
                else capDelta = 4;

                var rioLatamEntry = triggeredEvents.some(function(e) { return e.effect === 'rio_latam_entry'; });
                if (rioLatamEntry) ds.rioLatamShare += 8;

                if (ds.rioResponse === 'price_deterrence') { ds.rioLatamShare -= 4; gcpiDelta = 3; }
                else if (ds.rioResponse === 'deepen_chile') { ds.rioLatamShare -= 2; gcpiDelta = 6; }
                else if (ds.rioResponse === 'licensing_deal') { ds.rioLatamShare -= 1; gcpiDelta = 4; ipDelta -= 3; newLicenses += 5; }
                else { gcpiDelta = -2; }

                if (ds.competIntel) { gcpiDelta += 3; ds.rioLatamShare -= 2; }

                ds.peruPenetration += 1.5 + Math.random() * 2;
                ds.brazilPenetration += 1 + Math.random() * 2;
                ds.canadaPenetration += 2 + Math.random() * 2;

                newLicenses += Math.round(6 + Math.random() * 8);
                if (ds.australiaMode === 'wos_acquisition') newLicenses += Math.round(8 + Math.random() * 6);

                roundIRR = (ds.peruPenetration * 0.6 + ds.brazilPenetration * 0.5 + ds.canadaPenetration * 0.8 + ds.australiaPenetration * 1.0) * 0.25 + (Math.random() * 2 - 1);
            }

            if (period === 4) {
                ds.orgArchitecture = d.primary;
                ds.portfolioReview = d.portfolioReview || {};
                budgetUsed = 0;

                var markets = ['peru', 'brazil', 'canada', 'australia'];
                for (var ri = 0; ri < markets.length; ri++) {
                    var mk = markets[ri];
                    var review = (ds.portfolioReview[mk]) || 'maintain';
                    var penKey = mk + 'Penetration';
                    if (review === 'deepen') { ds[penKey] += 3 + Math.random() * 3; budgetUsed += 1.5; }
                    else if (review === 'restructure') { ds[penKey] *= 0.8; budgetUsed += 1.0; capDelta += 3; }
                    else if (review === 'exit') { ds[penKey] = 0; budgetUsed -= 0.5; }
                    else { ds[penKey] += 0.5 + Math.random(); }
                }

                var codelcoEvent = triggeredEvents.some(function(e) { return e.effect === 'codelco_standard'; });
                if (codelcoEvent) { newLicenses += 10; ipDelta += 10; }

                var activeMarkets = 0;
                var totalPen = 0;
                for (var mi2 = 0; mi2 < markets.length; mi2++) {
                    var p = ds[markets[mi2] + 'Penetration'];
                    if (p > 0) { activeMarkets++; totalPen += p; }
                }

                var orgFit = 0.7;
                var wosCount = [ds.peruMode, ds.brazilMode, ds.canadaMode, ds.australiaMode].filter(function(m) { return m === 'wos_greenfield' || m === 'wos_acquisition'; }).length;
                var jvCount = [ds.peruMode, ds.brazilMode, ds.canadaMode, ds.australiaMode].filter(function(m) { return m === 'jv'; }).length;

                if (ds.orgArchitecture === 'global_product' && wosCount >= 3) orgFit = 1.0;
                else if (ds.orgArchitecture === 'geographic' && activeMarkets >= 3) orgFit = 0.95;
                else if (ds.orgArchitecture === 'matrix' && jvCount >= 1 && wosCount >= 1) orgFit = 1.0;
                else if (ds.orgArchitecture === 'international_div' && activeMarkets <= 2) orgFit = 0.9;
                else orgFit = 0.75;

                roundIRR = totalPen * 0.35 * orgFit + (Math.random() * 3 - 1);
                gcpiDelta = Math.round((100 - ds.rioLatamShare) * orgFit * 0.15);
                newLicenses += Math.round(4 + Math.random() * 6);
            }

            ds.budgetSpent += budgetUsed;
            ds.budget = Math.max(0, 18.5 - ds.budgetSpent);
            ds.totalLicenses += newLicenses;
            ds.ipScore = Math.max(0, Math.min(100, ds.ipScore + ipDelta));
            ds.gcpi = Math.max(0, Math.min(100, ds.gcpi + gcpiDelta));
            ds.capabilityScore += capDelta;
            ds.portfolioIRR = (ds.portfolioIRR * (period - 1) + roundIRR) / period;
            ds.portfolioIRR = Math.round(ds.portfolioIRR * 100) / 100;

            ds.irrHistory.push(ds.portfolioIRR);
            ds.licensesHistory.push(ds.totalLicenses);
            ds.gcpiHistory.push(ds.gcpi);

            // v1.1.0 FIX: persist a normalized 0-100 score into domainState every
            // period so the grading/reporting layer can read it. results_utils.php
            // (express_resolveDomainScore) reads domainState.performance.overallScore
            // first, then top-level domainState.score. Without this the instructor
            // results panel shows an empty score. Uses the same model as the
            // completion summary (_computeScore) so client modal and server grade agree.
            var _score = this._computeScore(ds);
            ds.performance = { overallScore: _score.total, grade: _score.performance };
            ds.score = _score.total;

            var results = {
                period: period,
                roundIRR: Math.round(roundIRR * 100) / 100,
                portfolioIRR: ds.portfolioIRR,
                newLicenses: newLicenses,
                totalLicenses: ds.totalLicenses,
                ipScore: ds.ipScore,
                gcpi: ds.gcpi,
                overallScore: _score.total,
                budgetUsed: Math.round(budgetUsed * 100) / 100,
                budgetRemaining: Math.round(ds.budget * 100) / 100,
                eventsTriggered: triggeredEvents.length
            };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
            })(state.currentPeriod + 1), 500);

            return results;
        }

        _calcOLIfit(marketKey, entryMode) {
            var market = this.MARKETS[marketKey];
            if (!market) return 0.5;
            var mode = this.ENTRY_MODES[entryMode];
            if (!mode) return 0.5;

            var oFit = market.O / 10;
            var lFit = market.L / 10;
            var iFit = market.I / 10;
            var instPenalty = market.instDist / 10;

            var controlNeed = iFit;
            var controlMatch = 1 - Math.abs(controlNeed - mode.control / 5) * 0.5;

            var commitFit = 1 - (mode.commitment / 5) * instPenalty * 0.3;

            return Math.max(0.2, Math.min(1.0, (oFit * 0.3 + lFit * 0.25 + controlMatch * 0.25 + commitFit * 0.2)));
        }

