            uiManager.bind('irrDisplay', 'domainState.portfolioIRR',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('licensesDisplay', 'domainState.totalLicenses');
            uiManager.bind('ipScoreDisplay', 'domainState.ipScore');
            uiManager.bind('gcpiDisplay', 'domainState.gcpi');
        }

