        // v1.1.0: single source of truth for the 0-100 score, shared by
        // calculateResults() (persisted into domainState for grading/reporting)
        // and getPerformanceSummary() (completion modal). Scoring weights are
        // UNCHANGED from v1.0.0: IRR 35 / market breadth 25 / licenses 20 / IP 12 / GCPI 8.
        _computeScore(ds) {
            ds = ds || {};
            var irr = ds.portfolioIRR || 0;
            var licenses = (typeof ds.totalLicenses === 'number') ? ds.totalLicenses : 67;
            var ip = ds.ipScore || 0;
            var gcpi = ds.gcpi || 0;

            var irrScore = Math.min(35, Math.max(0, (irr / 18) * 35));
            var penMarkets = 0;
            if ((ds.peruPenetration || 0) >= 5) penMarkets++;
            if ((ds.brazilPenetration || 0) >= 5) penMarkets++;
            if ((ds.canadaPenetration || 0) >= 5) penMarkets++;
            if ((ds.australiaPenetration || 0) >= 5) penMarkets++;
            var mpbScore = Math.min(25, (penMarkets / 2) * 25);
            var opeScore = Math.min(20, Math.max(0, ((licenses - 67) / 45) * 20));
            var ipsScore = (ip / 100) * 12;
            var gcpiScore = Math.min(8, (gcpi / 65) * 8);
            var total = Math.round(irrScore + mpbScore + opeScore + ipsScore + gcpiScore);
            total = Math.max(0, Math.min(100, total));

            var performance = 'Developing Multilatina';
            if (total >= 80) performance = 'Global Mining Leader';
            else if (total >= 60) performance = 'Strong Multilatina';
            else if (total >= 40) performance = 'Emerging International Player';

            var insights = [];
            if (irr >= 18) insights.push('Excellent portfolio IRR — entry mode selections were well-calibrated to OLI conditions.');
            else insights.push('Portfolio IRR below target — review whether entry modes matched OLI framework predictions.');
            if (ip >= 80) insights.push('Strong IP protection — internalization advantages were properly managed.');
            else insights.push('IP protection compromised — licensing and JV modes exposed OrePlan Pro to partner opportunism.');
            if (gcpi >= 65) insights.push('Global competitive position strong — home market defended while expanding internationally.');
            else insights.push('Competitive position needs strengthening — Rio Pacific may have gained ground in LATAM.');

            return { total: total, performance: performance, insights: insights };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            // v1.1.0 FIX: history records store domainState directly (see
            // usf-state.addToHistory), NOT under .state. The old code read
            // last.state.domainState => always {} => every player scored ~0.
            var ds = last.domainState || (last.state && last.state.domainState) || {};
            var sc = this._computeScore(ds);
            return {
                totalScore: sc.total,
                portfolioIRR: ds.portfolioIRR || 0,
                totalLicenses: (typeof ds.totalLicenses === 'number') ? ds.totalLicenses : 67,
                ipScore: ds.ipScore || 0,
                gcpi: ds.gcpi || 0,
                performance: sc.performance,
                insights: sc.insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod;
            if (results.ipScore < 70) return window.mySimulation.t('hint_ip_risk');
            if (results.budgetRemaining < 2 && period < 4) return window.mySimulation.t('hint_budget_low');
            if (results.portfolioIRR < 10 && period >= 2) return window.mySimulation.t('hint_irr_low');
            if (results.gcpi < 40) return window.mySimulation.t('hint_gcpi_low');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundIRR', label: 'Round IRR (%)', i18nKey: 'col_round_irr', formatter: function(v) { return v.toFixed(1) + '%'; } },
                { key: 'results.portfolioIRR', label: 'Portfolio IRR (%)', i18nKey: 'col_portfolio_irr', formatter: function(v) { return v.toFixed(1) + '%'; } },
